use rhwp::DocumentCore;
use std::path::PathBuf;
// Compile in a small Cargo binary with rhwp pointing at the exact engine source.
fn host(d:&DocumentCore)->(usize,usize){let mut owners=d.document().sections[0].paragraphs.iter().enumerate().flat_map(|(p,q)|q.controls.iter().enumerate().filter_map(move|(c,v)|matches!(v,rhwp::model::control::Control::Table(_)).then_some((p,c))));let x=owners.next().unwrap();assert!(owners.next().is_none());x}
fn author(kind:&str,columns:u16)->DocumentCore{let mut d=DocumentCore::new_empty();d.create_blank_document_native().unwrap();d.set_page_def_native(0,r#"{"width":36000,"height":18000,"marginLeft":1800,"marginRight":1800,"marginTop":1800,"marginBottom":1800,"marginHeader":0,"marginFooter":0}"#).unwrap();if columns>1{d.set_column_def_native(0,columns,0,true,900).unwrap();}
 d.insert_text_native(0,0,0,&"앞 본문 현재 조판 😀 source prefix. ".repeat(3)).unwrap();let n=d.document().sections[0].paragraphs[0].text.chars().count();d.create_table_ex_native(0,0,n,if kind=="row"{12}else{1},1,false,None,None).unwrap();let(p,c)=host(&d);
 d.set_table_properties_native(0,p,c,&format!(r#"{{"pageBreak":{},"repeatHeader":false,"treatAsChar":false,"textWrap":"TopAndBottom","vertRelTo":"Para","vertAlign":"Top","horzRelTo":"Column","horzAlign":"Left","vertOffset":0,"horzOffset":0,"allowOverlap":false}}"#,if kind=="row"{2}else{1})).unwrap();let width=if columns==1{32400}else{15750};d.set_table_column_widths_native(0,p,c,vec![width-566]).unwrap();
 for row in 0..if kind=="row"{12}else{1}{let text=if kind=="row"{format!("행{row} 자료 😀 row source abc ").repeat(2)}else{"셀 분할 실제 source 😀 𠮷 abcdef. ".repeat(40)};d.insert_text_in_cell_native(0,p,c,row,0,0,&text).unwrap();}
 let tail=d.document().sections[0].paragraphs.len();d.insert_paragraph_native(0,tail).unwrap();d.insert_text_native(0,tail,0,"표 뒤 본문 tail source 🙂 is retained.").unwrap();d}

fn main(){let out=PathBuf::from(std::env::args().nth(1).expect("output directory"));std::fs::create_dir_all(&out).unwrap();for kind in ["row","cell"]{for columns in [1,2]{let d=author(kind,columns);let a=d.export_hwp_with_adapter_snapshot_with_report().unwrap();assert!(a.content_loss().is_empty());std::fs::write(out.join(format!("{kind}-{columns}col.hwp")),a.bytes()).unwrap();let native=DocumentCore::from_bytes(a.bytes()).unwrap();let x=native.export_hwpx_native_with_report().unwrap();assert!(x.content_loss().is_empty());std::fs::write(out.join(format!("{kind}-{columns}col.hwpx")),x.bytes()).unwrap();}}}
